/* @lc app=leetcode id=3679 lang=kotlin */ class Solution { fun minArrivalsToDiscard(arrivals: IntArray, w: Int, m: Int): Int = BooleanArray(arrivals.size).let { kept -> IntArray(100001).let { cnt -> arrivals.indices.fold(0) { d, i -> (if (i - w >= 0 && kept[i - w]) cnt.set(arrivals[i - w], cnt[arrivals[i - w]] - 1) else Unit).let { if (cnt[arrivals[i]] >= m) d + 1 else cnt.set(arrivals[i], cnt[arrivals[i]] + 1).also { kept[i] = true }.let { d } } } } } }